import { assertEquals } from "jsr:@std/assert";
import { CHARACTER_MENU_TABS } from "../src/display/ui/overlayUtils.js";
import { CHARACTER_MENU_TAB_GLYPHS, UI_ACTION_GLYPHS, UI_PET_STATE_GLYPHS } from "../src/display/ui/iconGlyphs.js";
import { basePalette } from "../src/display/palette/base.js";
import { getMonster } from "../src/rules/data/monsters.js";
import { buildClassDisplayData } from "../src/main/classDisplayData.js";

Deno.test("HUD action glyphs keep their established icon codepoints", () => {
  assertEquals(UI_ACTION_GLYPHS, {
    character: "@",
    bag: "🎒",
    cast: "✦",
    spells: "📖",
    shoot: "🏹",
    attack: "⚔",
    zap: "⚡",
    pray: "🙏",
    door: "🚪",
    postureBalanced: "⚖",
    postureAggressive: "⚔",
    postureGuarded: "🛡",
    wait: "⏳",
    search: "🔍",
    bug: "👾",
    petDefault: "🐾",
  });
});

Deno.test("pet state glyphs keep their established icon codepoints", () => {
  assertEquals(UI_PET_STATE_GLYPHS, {
    following: "🐾",
    staying: "⚓",
    fetching: "🦴",
    returning: "↩",
    guarding: "🛡️",
    aggressive: "⚔️",
    fleeing: "💨",
    idle: "💤",
  });
});

Deno.test("character menu tabs use the shared established glyph contract", () => {
  assertEquals(CHARACTER_MENU_TAB_GLYPHS, {
    character: "@",
    inventory: "🎒",
    equipment: "🛡️",
    quests: "📜",
    settings: "⚙️",
  });
  assertEquals(
    CHARACTER_MENU_TABS.map(({ key, icon }) => [key, icon]),
    [
      ["character", "@"],
      ["inventory", "🎒"],
      ["equipment", "🛡️"],
      ["quests", "📜"],
      ["settings", "⚙️"],
    ],
  );
});

Deno.test("character creation class icons keep their established glyphs", () => {
  const icons = Object.fromEntries(buildClassDisplayData().map((entry) => [entry.id, entry.icon]));
  assertEquals(icons, {
    warden: "🛡️",
    druid: "🌿",
    outlaw: "🗡️",
    archeologist: "⛏️",
    warlock: "🔮",
    mage: "🔥",
    mireborn: "🪷",
    pilgrim: "🙏",
    cleric: "✨",
    valkyrie: "🪽",
  });
});

Deno.test("named content glyphs that regressed before stay pinned", () => {
  assertEquals(basePalette.mailbox?.glyph, "📪");
  assertEquals(basePalette.mailbox_checking?.glyph, "📭");
  assertEquals(basePalette.mailbox_has_mail?.glyph, "📬");
  assertEquals(basePalette.mailbox_sent?.glyph, "📫");
  assertEquals(getMonster("ratatoskr")?.glyph, "🐿️");
});

Deno.test("display UI does not contain emoji font fallback hacks", async () => {
  const forbidden = [
    "preferEmojiPresentation",
    "font-variant-emoji",
    "fontVariantEmoji",
    "Apple Color Emoji",
    "Segoe UI Emoji",
    "Noto Color Emoji",
  ];
  const offenders = [];

  async function scanDir(dir) {
    for await (const entry of Deno.readDir(dir)) {
      const path = `${dir}/${entry.name}`;
      if (entry.isDirectory) {
        await scanDir(path);
      } else if (entry.isFile && path.endsWith(".js")) {
        const source = await Deno.readTextFile(path);
        for (const needle of forbidden) {
          if (source.includes(needle)) offenders.push(`${path}: ${needle}`);
        }
      }
    }
  }

  await scanDir("src/display/ui");
  assertEquals(offenders, []);
});

