  ctx.fillStyle = 'rgba(255,220,40,0.95)';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `bold ${0.32 * scale}px sans-serif`;
  ctx.fillText('!', cx, dy);

  ctx.restore();
}


